import React from 'react';
import ReactDOM from 'react-dom';
import {
  DataTable,
  TableContainer,
  Table,
  TableHead,
  TableBody,
  TableRow,
  TableHeader,
  TableCell,
  TableSelectAll,
  TableSelectRow,
  TableToolbar,
  TableToolbarSearch,
  TableBatchActions,
  TableBatchAction,
  TableToolbarContent,
} from 'carbon-components-react';

// Sample data: 3 total items
const initialRows = [
  {
    id: '1',
    name: 'Load Balancer 1',
    protocol: 'HTTP',
    port: 443,
    rule: 'Round robin',
    attachedGroups: 'Maureens VM Groups',
    status: 'Starting',
  },
  {
    id: '2',
    name: 'Load Balancer 2',
    protocol: 'HTTP',
    port: 80,
    rule: 'DNS delegation',
    attachedGroups: 'Andrews VM Groups',
    status: 'Active',
  },
  {
    id: '3',
    name: 'Load Balancer 3',
    protocol: 'HTTP',
    port: 3000,
    rule: 'Round robin',
    attachedGroups: 'Kevins VM Groups',
    status: 'Disabled',
  },
];

// Table column definitions
const headers = [
  { key: 'name', header: 'Name' },
  { key: 'protocol', header: 'Protocol' },
  { key: 'port', header: 'Port' },
  { key: 'rule', header: 'Rule' },
  { key: 'attachedGroups', header: 'Attached Groups' },
  { key: 'status', header: 'Status' },
];

function App() {
  return (
    <DataTable
      rows={initialRows}
      headers={headers}
      render={({
        rows,
        headers,
        getHeaderProps,
        getSelectionProps,
        getBatchActionProps,
        onInputChange,
        selectedRows,
      }) => (
        <TableContainer title="DataTable with batch actions">
          {/* Toolbar including search input */}
          <TableToolbar>
            <TableBatchActions {...getBatchActionProps()}>
              <TableBatchAction
                primaryFocus
                onClick={() => console.log('Batch action on', selectedRows)}
              >
                Do Something
              </TableBatchAction>
            </TableBatchActions>
            <TableToolbarSearch onChange={onInputChange} />
            <TableToolbarContent />
          </TableToolbar>

          {/* Table with selection checkboxes */}
          <Table>
            <TableHead>
              <TableRow>
                <TableSelectAll {...getSelectionProps()} />
                {headers.map(header => (
                  <TableHeader key={header.key} {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>

            <TableBody>
              {rows.map(row => (
                <TableRow key={row.id}>
                  <TableSelectRow {...getSelectionProps({ row })} />
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    />
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
